import { getProgramName } from './program_name.mjs';

const HELP_TEXT = 'show this help message and exit';
const NEGATIVE_INTEGER_EXPRESSION = /^-\p{Decimal_Number}+$/u;
const NEGATIVE_FLOAT_EXPRESSION = /^-\p{Decimal_Number}*\.\p{Decimal_Number}+$/u;

function buildUsage(programName) {
  return `usage: ${programName} [-h] --a A\n`;
}

function buildHelp(programName) {
  return `${buildUsage(programName)}\noptions:\n  -h, --help  ${HELP_TEXT}\n  --a A\n`;
}

function buildError(programName, message) {
  return `${buildUsage(programName)}${programName}: error: ${message}\n`;
}

function isNegativeNumberLike(token) {
  return (
    NEGATIVE_INTEGER_EXPRESSION.test(token) ||
    NEGATIVE_FLOAT_EXPRESSION.test(token)
  );
}

function canUseAsSeparateValue(token) {
  if (token === undefined) {
    return false;
  }

  if (token === '-') {
    return true;
  }

  if (!token.startsWith('-')) {
    return true;
  }

  return isNegativeNumberLike(token);
}

function isClusteredHelpToken(token) {
  return token.startsWith('-h') && token.length > 2 && !token.startsWith('-h=');
}

export function parseTest4Args(argv = process.argv) {
  const programName = getProgramName(argv);
  const args = argv.slice(2);
  let aValue = '';
  let hasAValue = false;
  const extras = [];
  let parsingOptions = true;

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index];

    if (!parsingOptions) {
      extras.push(token);
      continue;
    }

    if (token === '--help' || token === '-h' || isClusteredHelpToken(token)) {
      return {
        kind: 'help',
        exitCode: 0,
        output: buildHelp(programName),
      };
    }

    if (token.startsWith('--help=')) {
      return {
        kind: 'error',
        exitCode: 2,
        output: buildError(
          programName,
          `argument -h/--help: ignored explicit argument '${token.slice(7)}'`,
        ),
      };
    }

    if (token.startsWith('-h=')) {
      return {
        kind: 'error',
        exitCode: 2,
        output: buildError(
          programName,
          `argument -h/--help: ignored explicit argument '${token.slice(3)}'`,
        ),
      };
    }

    if (token === '--') {
      extras.push(token);
      parsingOptions = false;
      continue;
    }

    if (token === '--a') {
      const nextToken = args[index + 1];

      if (!canUseAsSeparateValue(nextToken)) {
        return {
          kind: 'error',
          exitCode: 2,
          output: buildError(programName, 'argument --a: expected one argument'),
        };
      }

      aValue = nextToken;
      hasAValue = true;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      aValue = token.slice(4);
      hasAValue = true;
      continue;
    }

    extras.push(token);
  }

  if (!hasAValue) {
    return {
      kind: 'error',
      exitCode: 2,
      output: buildError(programName, 'the following arguments are required: --a'),
    };
  }

  if (extras.length > 0) {
    return {
      kind: 'error',
      exitCode: 2,
      output: buildError(
        programName,
        `unrecognized arguments: ${extras.join(' ')}`,
      ),
    };
  }

  return {
    kind: 'ok',
    exitCode: 0,
    aValue,
  };
}

import {
  ASCII_SEPARATOR_RUN_EXPRESSION,
  DEFAULT_DELIMITER,
  trimDelimiterEdges,
} from './ascii_separators.mjs';

export function slugify(value, delimiter = DEFAULT_DELIMITER) {
  const text = String(value).toLowerCase();
  const normalized = text.replace(ASCII_SEPARATOR_RUN_EXPRESSION, delimiter);
  const trimmed = trimDelimiterEdges(normalized, delimiter);

  if (trimmed.length > 0 || text.length === 0) {
    return trimmed;
  }

  return delimiter;
}

export const DEFAULT_DELIMITER = '_';
export const ASCII_SEPARATOR_CHARACTERS =
  " \t\n\r\u000b\f!\"#$%&'()*+,-./:;<=>?@[]^_`{|}~";

function escapeForCharacterClass(value) {
  return value.replace(/[\\\]\^-]/gu, '\\$&');
}

export const ASCII_SEPARATOR_RUN_EXPRESSION = new RegExp(
  `[${escapeForCharacterClass(ASCII_SEPARATOR_CHARACTERS)}]+`,
  'gu',
);

export function trimDelimiterEdges(text, delimiter = DEFAULT_DELIMITER) {
  let start = 0;
  let end = text.length;

  while (start < end && text.slice(start, start + delimiter.length) === delimiter) {
    start += delimiter.length;
  }

  while (end > start && text.slice(end - delimiter.length, end) === delimiter) {
    end -= delimiter.length;
  }

  return text.slice(start, end);
}

import { parseTest4Args } from '../cli/test4_parser.mjs';
import { slugify } from '../slugify/slugify.mjs';

export function runTest4(argv = process.argv, io = process) {
  const parsed = parseTest4Args(argv);

  if (parsed.kind === 'help') {
    io.stdout.write(parsed.output);
    return parsed.exitCode;
  }

  if (parsed.kind === 'error') {
    io.stderr.write(parsed.output);
    return parsed.exitCode;
  }

  io.stdout.write(`${slugify(parsed.aValue)}\n`);
  return parsed.exitCode;
}

export function getProgramName(argv) {
  const candidate = argv[1] ?? argv[0] ?? 'program';
  const parts = String(candidate).split(/[\\/]/u);
  return parts[parts.length - 1] || 'program';
}

